      text: "At Open Arms, therapeutic foster parents work alongside a clinical team that may include licensed therapists, case managers, and behavioral health specialists. This team approach means you're never expected to handle complex situations alone. Regular check-ins, treatment planning meetings, and 24/7 on-call support are standard.",
