        type: "p",
        text: "Fostering can feel like trying to hold a wild storm. Kids arrive with trauma. Some hoard food, others shut down, and foster parents juggle those needs while keeping life steady. Without a net, the weight can overwhelm. We provide resources to lighten that load, ensuring no one feels alone. Training, caseworkers, and peer circles form a web that catches foster parents when the days get long.",
