        text: "A support system isn't just for foster parents. It's for the kids. When foster parents have tools and a team, they can focus on the small wins: a kid who doodles instead of hiding, another who sits at dinner without stashing food. These moments, built on training, caseworker advice, and peer chats, show kids that this home is safe. Without support, those wins might slip. With it, things come together, making a house feel like a warm home.",
