        type: "p",
        text: "Fostering has its storms. Kids might bolt, scared by a loud noise, or shut down for days. We provide strategies to navigate these: wait out a runaway, offer a toy bin instead of a lecture. A foster parent might face a kid who won't eat; peer advice, like a no-pressure Lego bin, can spark a grunted \"thanks\" in time. These aren't instant fixes. They're steps forward, made possible by a net of support that keeps foster parents from crumbling.",
